async function startRequestPreview(){
 const triageConversation={...conversation,_id:new mongoose.Types.ObjectId(),externalConversationId:'fixture-browser-triage',customerName:'Isolated browser customer',sourceMetadata:{...conversation.sourceMetadata,externalContactId:'fixture-browser-contact'}};
 const triageMessage={...message,_id:new mongoose.Types.ObjectId(),conversationId:triageConversation._id,externalMessageId:'fixture-browser-message',sentAt:new Date(),text:'Please pause my meals tomorrow and confirm the new dates'};
 await source('serviceconversations',triageConversation);await source('servicemessages',triageMessage);await source('servicesourcecontacts',{_id:new mongoose.Types.ObjectId(),scope:'fixture',externalContactId:'fixture-browser-contact',matchState:'unmatched'});

 const {default:express}=await import('express');const {default:router}=await import('../routes/customerService.js');const {default:data}=await import('../routes/customerServiceData.js');const {default:customers}=await import('../routes/customerServiceCustomers.js');
 const app=express();app.use(express.json());const tokens=new Map();for(const [label,user] of Object.entries({head,staff,approver})){user.profile={firstName:'Isolated',lastName:label};user.permissions={customerService:true};user.permissionsConfigured=true;user.serviceOnly=true;tokens.set(label,{token:randomUUID(),user});}
 app.set('customerServiceAuth',{authenticate:async header=>{const entry=[...tokens.values()].find(e=>header==='Bearer '+e.token);if(!entry)throw Object.assign(Error('Expired isolated session'),{statusCode:401});return {user:entry.user};}});
 app.get('/test/session/:role',(req,res)=>{const e=tokens.get(req.params.role);if(!e)return res.sendStatus(404);res.type('html').send('<script>localStorage.setItem("token",'+JSON.stringify(e.token)+');localStorage.setItem("user",'+JSON.stringify(JSON.stringify(e.user))+');location.replace("/customer-service/chats");</script>');});
 app.get('/api/auth/me',async(req,res)=>{try{const a=await app.get('customerServiceAuth').authenticate(req.headers.authorization);res.json({success:true,data:{user:a.user}});}catch{res.sendStatus(401);}});
 app.use('/api/customer-service',customers,data,router);app.use(express.static('client/build'));app.get('*',(req,res)=>res.sendFile(process.cwd()+'/client/build/index.html'));
 const port=Number(process.env.CUSTOMER_SERVICE_REQUEST_PREVIEW_PORT||51002);const server=app.listen(port,'127.0.0.1');
 fs.mkdirSync('tmp/qa/workflow-v2',{recursive:true,mode:0o700});
 fs.writeFileSync('tmp/qa/workflow-v2/isolated-preview.private.json',JSON.stringify({port,database:name,tokens:Object.fromEntries(tokens),requestId:String(r._id)}),{mode:0o600});
 console.log('Isolated request preview listening on '+port);
 process.on('SIGTERM',async()=>{server.close();configureCloudInbox(null);await pool.end();await admin.query('DROP DATABASE '+name);await admin.end();process.exit(0);});
}

run('explicit combined type saves one neutral classification without guessing spam or vendor; retries retain source and history',async()=>{
 const f=await reviewFixture('manual-combined-type'),payload={operation:'create',conversationId:String(f.cid),issueKey:randomUUID(),classificationOnly:true,classification:{kind:'non_customer'}},requestId=randomUUID();
 const snapshot=async()=>(await pool.query("SELECT kind,id,sha256 FROM gallabox_private.inbox_record WHERE (kind='serviceconversations' AND id=$1) OR (kind='servicemessages' AND body->>'conversationId'=$1) ORDER BY kind,id",[String(f.cid)])).rows;const before=await snapshot();await assert.rejects(commandRequest({...payload,actor:staff,requestId}),e=>e.statusCode===403);
 const saved=await commandRequest({...payload,actor:head,requestId});assert.equal(saved.classification.kind,'non_customer');assert.equal(saved.status,'non_customer');assert.equal(saved.ownerId,null);assert.equal(saved.nextAction,undefined);assert.equal(saved.resolution.basis,'staff_classification');assert.equal(saved.resolution.outcomeLabel,'Spam / Vendor');assert.equal(saved.resolution.evidenceMessageId,String(f.mid));assert.equal(saved.history.length,1);assert.equal(saved.history[0].event,'non_customer_classified');assert.deepEqual(await snapshot(),before);
 const replay=await commandRequest({...payload,actor:head,requestId});assert.equal(String(replay._id),String(saved._id));assert.equal(await Request.countDocuments({conversationId:f.cid}),1);const page=await listRequests({actor:head,filters:{queue:'conversation',conversationId:String(f.cid)}});assert.deepEqual(page.statusCounts,{open:0,resolved:0,non_customer:1});
 await assert.rejects(commandRequest({...payload,actor:head,requestId:randomUUID()}),e=>e.statusCode===409);
});
